            set => _tags = value;
        }

        /// <summary>
        /// Edge instance update time
        /// </summary>
        [Input("updateTime")]
        public Input<int>? UpdateTime { get; set; }

        /// <summary>
        /// Private network ID
        /// </summary>
        [Input("vpcIdentity")]
        public Input<string>? VpcIdentity { get; set; }

        public VeenState()
        {
        }
        public static new VeenState Empty => new VeenState();
    }
}
